import{_ as o}from"./chunks/settings-robot.pc.ko.CimpdZDI.js";import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.D47SInms.js";const m=JSON.parse('{"title":"페이로드 설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/payload_setting.md","filePath":"ko/manual/troubleshooting/payload_setting.md","lastUpdated":1791600043000}'),s={name:"ko/manual/troubleshooting/payload_setting.md"};function n(l,t,i,c,h,g){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="페이로드-설정" tabindex="-1">페이로드 설정 <a class="header-anchor" href="#페이로드-설정" aria-label="Permalink to &quot;페이로드 설정&quot;">​</a></h1><p>로봇에 짐을 얹으면 무게 중심이 옮겨져 보행이 흔들립니다. <strong>설정 › 페이로드 설정</strong>의 <code>로봇 페이로드 설정</code>에 적재물의 <strong>질량과 무게중심</strong>을 등록하면 그 값이 보행 동역학에 반영되어 안정성이 회복됩니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>정확한 사양을 몰라도 <strong>대략적인 질량과 무게중심 높이(Z)</strong>는 넣어 두시길 권합니다. 근사값만으로도 보행이 눈에 띄게 안정되며, <strong>비워 두는 것이 가장 불리합니다</strong>.</p></div></div><h2 id="사전-준비" tabindex="-1">사전 준비 <a class="header-anchor" href="#사전-준비" aria-label="Permalink to &quot;사전 준비&quot;">​</a></h2><ul><li>로봇을 평평하고 안전한 바닥에 둡니다.</li><li>앱이 로봇에 연결되어 있어야 합니다 — 연결이 없으면 슬롯을 읽지 못합니다.</li><li>적재물의 질량과, 로봇 몸통 기준 무게중심 위치(X/Y/Z)를 미리 확인합니다.</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><p><img src="'+o+'" alt="로봇 파라미터 — 로봇 페이로드 설정"></p><p>넓은 화면에서는 좌우 2단, 좁은 화면에서는 위아래로 쌓입니다.</p><table tabindex="0"><thead><tr><th>자리</th><th>내용</th></tr></thead><tbody><tr><td>왼쪽 위</td><td><strong>3D 미리보기</strong> — 등록된 페이로드가 마커로 표시됩니다. 마커를 누르면 그 슬롯이 선택되고, X/Y/Z 화살표를 끌어 위치를 옮길 수 있습니다</td></tr><tr><td>왼쪽 아래</td><td><strong>선택 슬롯 편집창</strong> — <code>Mass</code> · <code>X</code> · <code>Y</code> · <code>Z</code> 네 칸. 아무것도 고르지 않았으면 첫 슬롯이 대상입니다</td></tr><tr><td>오른쪽 위</td><td><strong>슬롯 표</strong> — 로봇이 보고한 슬롯 목록. <code>●</code>는 고정 페이로드, <code>◻</code>는 사용자 슬롯입니다</td></tr><tr><td>오른쪽 아래</td><td><strong>합계</strong>와 <code>Get</code> · <code>Set Payload</code> 버튼</td></tr></tbody></table><h2 id="설정-절차" tabindex="-1">설정 절차 <a class="header-anchor" href="#설정-절차" aria-label="Permalink to &quot;설정 절차&quot;">​</a></h2><ol><li><strong>슬롯을 고릅니다.</strong> 오른쪽 표에서 등록할 슬롯을 누릅니다. 체크박스를 켜면 <strong>장착</strong>으로 표시되고, 로봇이 가지고 있는 카탈로그 기본값이 자동으로 채워집니다.</li><li><strong>값을 입력합니다.</strong> 왼쪽 편집창에서 <code>Mass</code>(kg)와 <code>X</code> · <code>Y</code> · <code>Z</code>(m)를 넣습니다. 칸을 직접 눌러 숫자를 치거나, <code>−</code> · <code>+</code> 로 조절합니다. 한 번에 얼마씩 움직일지는 편집창 오른쪽 위의 <strong>간격</strong> (<code>0.001</code> · <code>0.01</code> · <code>0.1</code> · <code>1</code>)으로 정합니다.</li><li><strong>합계를 확인합니다.</strong> 편집창 아래 합계 상자에 전체 질량과 합성 무게중심이 나옵니다. 상한을 넘으면 빨간 글씨로 알려 주고 <code>Set Payload</code> 가 눌리지 않습니다.</li><li><strong><code>Set Payload</code></strong> 를 누른 뒤 확인 창에서 <strong><code>적용</code></strong> 을 누릅니다. 확인 창에 장착 슬롯 수와 합계가 다시 표시됩니다. <strong>체크를 해제한 슬롯은 질량 0으로 전송되어 비워집니다.</strong></li><li>적용되면 로봇 값을 다시 읽어 화면이 갱신되고 <em>적용됨 (로봇 값으로 재확인)</em> 이 표시됩니다. 새 값은 곧바로 보행 동역학에 들어가며 1~2초에 걸쳐 서서히 반영됩니다.</li></ol><p><code>Get</code>은 로봇에 저장된 슬롯을 다시 읽어옵니다 — <strong>편집 중이던 값은 버려집니다.</strong></p><h2 id="허용-범위" tabindex="-1">허용 범위 <a class="header-anchor" href="#허용-범위" aria-label="Permalink to &quot;허용 범위&quot;">​</a></h2><p>편집창 맨 아래 줄에 지금 로봇이 허용하는 범위가 그대로 표시됩니다. 로봇이 값을 알려 주지 않는 구형 소프트웨어에서는 아래 기본값을 씁니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>범위</th></tr></thead><tbody><tr><td>슬롯별 질량</td><td>0 ~ 20 kg</td></tr><tr><td>전체 합계</td><td>20 kg 이하</td></tr><tr><td>무게중심</td><td>|X| ≤ 0.5 m · |Y| ≤ 0.3 m · |Z| ≤ 0.4 m</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>질량·무게중심을 바꾼 뒤에는 <strong>무게 중심 보정(ZMP)을 다시 수행</strong>하시길 권합니다. 보정값은 그때의 적재 상태를 기준으로 저장되므로, 짐이 바뀌면 이전 보정이 맞지 않습니다. 보정은 <strong>정비 › 캘리브레이션</strong>에 있습니다.</p></div></div><h2 id="잘-안-될-때" tabindex="-1">잘 안 될 때 <a class="header-anchor" href="#잘-안-될-때" aria-label="Permalink to &quot;잘 안 될 때&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면에 나오는 말</th><th>뜻과 조치</th></tr></thead><tbody><tr><td><em>읽기 실패 — 로봇 연결 확인</em></td><td>로봇과 연결되어 있지 않습니다. <a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a>을 확인하세요</td></tr><tr><td><em>구버전 로봇 — 13슬롯 미지원</em></td><td>로봇 소프트웨어가 슬롯 방식을 지원하지 않습니다. <a href="/RBQ/nightly/ko/manual/gui/software-update.html">로봇 소프트웨어 업데이트</a> 후 다시 시도하세요</td></tr><tr><td><em>합계가 상한 20 kg 을 넘습니다</em></td><td>슬롯을 줄이거나 질량을 낮추세요. 넘는 동안에는 전송되지 않습니다</td></tr><tr><td><em>적용 실패 — 허용 범위 초과이거나 연결 끊김</em></td><td>위 허용 범위를 벗어났거나 전송 중 연결이 끊겼습니다</td></tr></tbody></table><p>일부 로봇은 고정 장비가 이미 로봇 쪽 설정에 반영되어 있어 <strong>사용자 슬롯 한 칸만</strong> 보입니다. 슬롯 수가 예상과 다르면 정상 동작이니 그대로 쓰시면 됩니다.</p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>어느 슬롯에 어떤 값을 넣었는지, 합계는 얼마였는지, 그리고 화면에 나온 문구를 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',22)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
